fn reconcile_re_registers_an_identity_the_user_added_back_after_forgetting() {
    keychain::clear_for_test();
    let did = "did:plc:forgottenthenreadded";
    keychain::store_item("did", did.as_bytes()).unwrap();

    // Forget, then import again: registering retracts the tombstone, so a later stranded
    // create for the same DID is reconcilable again rather than permanently blacklisted.
    identity_store::IdentityStore.add_identity(did).unwrap();
