    store.add_identity("did:plc:stays").expect("add stays");
    store.remove_identity("did:plc:goes").expect("remove goes");

    assert!(store.is_forgotten("did:plc:goes"));
    assert!(!store.is_forgotten("did:plc:stays"));
}

